import clsx from "clsx";
import "./entry-tree.css";

interface EntriesRouteEntryTreeProps {
  entries: Array<{id: string; label: string}>;
  selectedId?: string;
}

export const EntriesRouteEntryTree = ({entries, selectedId}: EntriesRouteEntryTreeProps) => (
  <ul className={clsx("entriesRoute_entryTree", selectedId && "entriesRoute_entryTree--selected")}>
    {entries.map((entry) => (
      <li key={entry.id}>{entry.label}</li>
    ))}
  </ul>
);

.entriesRoute_entryTree {
  display: grid;
  gap: 0.5rem;
  margin: 0;
  padding: 0;
  list-style: none;
}

.entriesRoute_entryTree--selected {
  font-weight: 600;
}
